// IoK8SApiBatchV1PodFailurePolicy PodFailurePolicy describes how failed pods influence the backoffLimit.
type IoK8SApiBatchV1PodFailurePolicy = PodFailurePolicy

// PodFailurePolicy PodFailurePolicy describes how failed pods influence the backoffLimit.
type PodFailurePolicy struct {
	// Rules A list of pod failure policy rules. The rules are evaluated in order. Once a rule matches a Pod failure, the remaining of the rules are ignored. When no rule matches the Pod failure, the default handling applies - the counter of pod failures is incremented and it is checked against the backoffLimit. At most 20 elements are allowed.
	Rules *[]IoK8SApiBatchV1PodFailurePolicyRule `json:"rules,omitempty"`
}

// IoK8SApiBatchV1PodFailurePolicyOnExitCodesRequirement PodFailurePolicyOnExitCodesRequirement describes the requirement for handling a failed pod based on its container exit codes. In particular, it lookups the .state.terminated.exitCode for each app container and init container status, represented by the .status.containerStatuses and .status.initContainerStatuses fields in the Pod status, respectively. Containers completed with success (exit code 0) are excluded from the requirement check.
type IoK8SApiBatchV1PodFailurePolicyOnExitCodesRequirement = PodFailurePolicyOnExitCodesRequirement

// PodFailurePolicyOnExitCodesRequirement PodFailurePolicyOnExitCodesRequirement describes the requirement for handling a failed pod based on its container exit codes. In particular, it lookups the .state.terminated.exitCode for each app container and init container status, represented by the .status.containerStatuses and .status.initContainerStatuses fields in the Pod status, respectively. Containers completed with success (exit code 0) are excluded from the requirement check.
type PodFailurePolicyOnExitCodesRequirement struct {
	// ContainerName Restricts the check for exit codes to the container with the specified name. When null, the rule applies to all containers. When specified, it should match one the container or initContainer names in the pod template.
	ContainerName *string `json:"containerName,omitempty"`

	// Operator Represents the relationship between the container exit code(s) and the specified values. Containers completed with success (exit code 0) are excluded from the requirement check. Possible values are:
	//
	// - In: the requirement is satisfied if at least one container exit code
	//   (might be multiple if there are multiple containers not restricted
	//   by the 'containerName' field) is in the set of specified values.
	// - NotIn: the requirement is satisfied if at least one container exit code
	//   (might be multiple if there are multiple containers not restricted
	//   by the 'containerName' field) is not in the set of specified values.
	// Additional values are considered to be added in the future. Clients should react to an unknown operator by assuming the requirement is not satisfied.
	Operator *string `json:"operator,omitempty"`

	// Values Specifies the set of values. Each returned container exit code (might be multiple in case of multiple containers) is checked against this set of values with respect to the operator. The list of values must be ordered and must not contain duplicates. Value '0' cannot be used for the In operator. At least one element is required. At most 255 elements are allowed.
	Values *[]int32 `json:"values,omitempty"`
}

// IoK8SApiBatchV1PodFailurePolicyOnPodConditionsPattern PodFailurePolicyOnPodConditionsPattern describes a pattern for matching an actual pod condition type.
type IoK8SApiBatchV1PodFailurePolicyOnPodConditionsPattern = PodFailurePolicyOnPodConditionsPattern

// PodFailurePolicyOnPodConditionsPattern PodFailurePolicyOnPodConditionsPattern describes a pattern for matching an actual pod condition type.
type PodFailurePolicyOnPodConditionsPattern struct {
	// Status Specifies the required Pod condition status. To match a pod condition it is required that the specified status equals the pod condition status. Defaults to True.
	Status *string `json:"status,omitempty"`

	// Type Specifies the required Pod condition type. To match a pod condition it is required that specified type equals the pod condition type.
	Type *string `json:"type,omitempty"`
}

// IoK8SApiBatchV1PodFailurePolicyRule PodFailurePolicyRule describes how a pod failure is handled when the requirements are met. One of onExitCodes and onPodConditions, but not both, can be used in each rule.
type IoK8SApiBatchV1PodFailurePolicyRule = PodFailurePolicyRule

// PodFailurePolicyRule PodFailurePolicyRule describes how a pod failure is handled when the requirements are met. One of onExitCodes and onPodConditions, but not both, can be used in each rule.
type PodFailurePolicyRule struct {
	// Action Specifies the action taken on a pod failure when the requirements are satisfied. Possible values are:
	//
	// - FailJob: indicates that the pod's job is marked as Failed and all
	//   running pods are terminated.
	// - FailIndex: indicates that the pod's index is marked as Failed and will
	//   not be restarted.
	// - Ignore: indicates that the counter towards the .backoffLimit is not
	//   incremented and a replacement pod is created.
	// - Count: indicates that the pod is handled in the default way - the
	//   counter towards the .backoffLimit is incremented.
	// Additional values are considered to be added in the future. Clients should react to an unknown action by skipping the rule.
	Action *string `json:"action,omitempty"`

	// OnExitCodes Represents the requirement on the container exit codes.
	OnExitCodes *IoK8SApiBatchV1PodFailurePolicyOnExitCodesRequirement `json:"onExitCodes,omitempty"`

	// OnPodConditions Represents the requirement on the pod conditions. The requirement is represented as a list of pod condition patterns. The requirement is satisfied if at least one pattern matches an actual pod condition. At most 20 elements are allowed.
	OnPodConditions *[]IoK8SApiBatchV1PodFailurePolicyOnPodConditionsPattern `json:"onPodConditions,omitempty"`
}

// IoK8SApiBatchV1SuccessPolicy SuccessPolicy describes when a Job can be declared as succeeded based on the success of some indexes.
type IoK8SApiBatchV1SuccessPolicy = SuccessPolicy

// SuccessPolicy SuccessPolicy describes when a Job can be declared as succeeded based on the success of some indexes.
type SuccessPolicy struct {
	// Rules rules represents the list of alternative rules for the declaring the Jobs as successful before `.status.succeeded >= .spec.completions`. Once any of the rules are met, the "SuccessCriteriaMet" condition is added, and the lingering pods are removed. The terminal state for such a Job has the "Complete" condition. Additionally, these rules are evaluated in order; Once the Job meets one of the rules, other rules are ignored. At most 20 elements are allowed.
	Rules *[]IoK8SApiBatchV1SuccessPolicyRule `json:"rules,omitempty"`
}

// IoK8SApiBatchV1SuccessPolicyRule SuccessPolicyRule describes rule for declaring a Job as succeeded. Each rule must have at least one of the "succeededIndexes" or "succeededCount" specified.
type IoK8SApiBatchV1SuccessPolicyRule = SuccessPolicyRule

// SuccessPolicyRule SuccessPolicyRule describes rule for declaring a Job as succeeded. Each rule must have at least one of the "succeededIndexes" or "succeededCount" specified.
type SuccessPolicyRule struct {
	// SucceededCount succeededCount specifies the minimal required size of the actual set of the succeeded indexes for the Job. When succeededCount is used along with succeededIndexes, the check is constrained only to the set of indexes specified by succeededIndexes. For example, given that succeededIndexes is "1-4", succeededCount is "3", and completed indexes are "1", "3", and "5", the Job isn't declared as succeeded because only "1" and "3" indexes are considered in that rules. When this field is null, this doesn't default to any value and is never evaluated at any time. When specified it needs to be a positive integer.
	SucceededCount *int32 `json:"succeededCount,omitempty"`

	// SucceededIndexes succeededIndexes specifies the set of indexes which need to be contained in the actual set of the succeeded indexes for the Job. The list of indexes must be within 0 to ".spec.completions-1" and must not contain duplicates. At least one element is required. The indexes are represented as intervals separated by commas. The intervals can be a decimal integer or a pair of decimal integers separated by a hyphen. The number are listed in represented by the first and last element of the series, separated by a hyphen. For example, if the completed indexes are 1, 3, 4, 5 and 7, they are represented as "1,3-5,7". When this field is null, this field doesn't default to any value and is never evaluated at any time.
	SucceededIndexes *string `json:"succeededIndexes,omitempty"`
}

